function x({registerIndicator:b,sourceValues:y,nulls:M}){b({id:"oa-gwma",name:"Gaussian-Weighted Moving Average (GWMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"sigma",type:"number",label:"Sigma",default:.4,min:.1,max:1,step:.1,tooltip:"Controls the width of the Gaussian bell curve. Lower values make the curve narrower."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"gwma",type:"line",title:"GWMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,r){const N=Math.max(1,Math.min(5e3,Math.floor(Number(r.period)||10))),s=Number(r.sigma),k=Number.isFinite(s)&&s>0?Math.min(1,Math.max(.1,s)):.4,c=y(n,r.source??"close"),m=new Array(n.length).fill(NaN);let o=[],h=-1;for(let e=0;e<n.length;e++){const t=Math.min(e+1,N);if(t!==h){o=new Array(t).fill(0);const i=(t-1)/2,l=1/(k*t);let f=0;for(let a=0;a<t;a++){const d=(a-i)*l,w=Math.exp(-.5*d*d);o[a]=w,f+=w}const v=f>0?1/f:0;for(let a=0;a<t;a++)o[a]*=v;h=t}let p=0,u=0;for(let i=0;i<t;i++){const l=c[e-i];Number.isFinite(l)&&(p+=l*o[i],u+=o[i])}const g=u!==0?p/u:NaN;Number.isFinite(g)?m[e]=g:Number.isFinite(c[e])&&(m[e]=c[e])}return{gwma:M(m)}}})}export{x as default};
